:root {
  --bg: #e9dfcf;
  --bg-2: #f5efe6;
  --bg-3: #d6c5ae;
  --panel: rgba(255, 251, 245, 0.82);
  --panel-strong: rgba(255, 252, 247, 0.94);
  --panel-tint: rgba(243, 233, 216, 0.86);
  --ink: #1f2430;
  --ink-soft: #49505c;
  --muted: #746d63;
  --line: rgba(92, 74, 49, 0.16);
  --line-strong: rgba(92, 74, 49, 0.28);
  --accent: #b45c3d;
  --accent-2: #2d5b67;
  --accent-3: #9d7a2f;
  --accent-4: #7f8f67;
  --good: #226b44;
  --bad: #8a3030;
  --shadow: 0 24px 80px rgba(65, 48, 27, 0.12);
  --shadow-soft: 0 16px 38px rgba(65, 48, 27, 0.08);
  --radius-xl: 32px;
  --radius-lg: 24px;
  --radius-md: 18px;
  --radius-sm: 14px;
  --max-width: 1440px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  font-family: "Manrope", "Segoe UI", sans-serif;
  background:
    radial-gradient(circle at top left, rgba(45, 91, 103, 0.18), transparent 28%),
    radial-gradient(circle at top right, rgba(180, 92, 61, 0.16), transparent 24%),
    radial-gradient(circle at 20% 80%, rgba(157, 122, 47, 0.11), transparent 20%),
    linear-gradient(180deg, #fbf6ef 0%, var(--bg-2) 26%, var(--bg) 72%, var(--bg-3) 100%);
}

body::before,
body::after {
  content: "";
  position: fixed;
  z-index: -1;
  inset: auto;
  pointer-events: none;
  filter: blur(4px);
}

body::before {
  top: 6rem;
  left: -6rem;
  width: 18rem;
  height: 18rem;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 248, 234, 0.95), rgba(255, 248, 234, 0));
}

body::after {
  right: -4rem;
  bottom: 4rem;
  width: 16rem;
  height: 16rem;
  border-radius: 34% 66% 65% 35% / 42% 37% 63% 58%;
  background: radial-gradient(circle, rgba(45, 91, 103, 0.14), rgba(45, 91, 103, 0));
}

a {
  color: var(--accent-2);
  text-decoration: none;
}

a:hover {
  color: var(--accent);
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
input,
textarea,
select,
.nav-link,
.card,
.metric-card,
.question-card,
.lab-note,
.record-pill,
.badge,
.chat-shell {
  transition:
    background-color 180ms ease,
    border-color 180ms ease,
    color 180ms ease,
    box-shadow 180ms ease,
    transform 180ms ease;
}

.app-shell {
  width: min(calc(100% - 2rem), var(--max-width));
  margin: 0 auto 2rem;
}

.site-header {
  position: relative;
  z-index: 50;
  margin-bottom: 1.4rem;
  padding: 1.1rem;
  border: 1px solid rgba(92, 74, 49, 0.15);
  border-radius: 0 0 34px 34px;
  background:
    linear-gradient(135deg, rgba(255, 254, 251, 0.98), rgba(245, 235, 220, 0.96)),
    rgba(255, 255, 255, 0.96);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
  transition:
    box-shadow 180ms ease,
    background-color 180ms ease,
    border-color 180ms ease;
}

.site-header::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.85), rgba(180, 92, 61, 0.1), rgba(45, 91, 103, 0.14));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

