{% extends "base.html" %}
{% block content %}
<section class="card">
  <p class="eyebrow">Guardrails</p>
  <h2>Prevent scouting notes from pretending to be scoreboard truth.</h2>
  {% for warning in warnings %}
  <article class="question-card">{{ warning }}</article>
  {% endfor %}
</section>
<section class="card">
  <h2>Review Standard</h2>
  <p>Every ML result should declare whether it has lookahead bias risk, leakage risk, reused validation exposure, survivorship distortion, repeated-test fatigue, and whether any live confirmation exists.</p>
</section>
{% endblock %}

{% extends "base.html" %}
{% block content %}
{% for row in rows %}
<section class="card">
  <h2>{{ row.strategy_name }}</h2>
  <p><strong>Why promoted:</strong> {{ row.promotion_reason }}</p>
  <p><strong>Supporting evidence:</strong> {{ row.supporting_evidence }}</p>
  <p><strong>Entered dry run:</strong> {{ row.entered_dry_run }}</p>
  <p><strong>Removed if removed:</strong> {{ row.removal_reason or 'Still active' }}</p>
</section>
{% endfor %}
{% endblock %}

{% extends "base.html" %}
{% block content %}
<section class="card">
  <div class="section-head">
    <div>
      <p class="eyebrow">Shift Scheduler</p>
      <h2>Development Runtime Rotation</h2>
      <p>Local time: {{ current_time_local }}</p>
    </div>
    <a href="/development">Back to Dev League</a>
  </div>
</section>

{% for schedule in schedules %}
<section class="card">
  <h2>{{ schedule.tier_label }}</h2>
  <div class="team-card-grid">
    {% for shift in schedule.shifts %}
    <article class="card franchise-card">
      <p class="eyebrow">{{ shift.label }}{% if shift.is_active %} · Active{% endif %}</p>
      <h3>{{ shift.window }}</h3>
      <p>{{ shift.candidates|length }} assigned candidate{{ "" if shift.candidates|length == 1 else "s" }}</p>
      {% for candidate in shift.candidates %}
      <p><a href="/development/candidates/{{ candidate.id }}">{{ candidate.name }}</a> · {{ candidate.runtime_status }}{% if candidate.latest_post_shift_grade %} · {{ candidate.latest_post_shift_grade }} {{ candidate.latest_post_shift_decision_label }}{% endif %}</p>
      {% else %}
      <p>No candidates assigned yet.</p>
      {% endfor %}
    </article>
    {% endfor %}
  </div>
</section>
{% endfor %}
{% endblock %}
